// Author: MiYu. Append Lua logs without writing into the original game installation.
#include "lua_file_log.h"
#include <cwctype>
#include <memory>

namespace war3 {
LuaFileLog::LuaFileLog(fs::path dataRoot):dataRoot_(std::move(dataRoot)){setPath("logs\\jass.log");}
void LuaFileLog::setPath(std::string_view value){if(value.empty() || value.size()>4096 || value.find('\0')!=value.npos || value.find(':')!=value.npos)throw std::runtime_error("Invalid Lua log path");fs::path path(wide(value));if(path.is_absolute() || path.has_root_name() || path.has_root_directory())throw std::runtime_error("Invalid Lua log path");unsigned count=0;for(auto& part:path){auto text=part.wstring();if(text.empty() || text==L"." || text==L".." || text.size()>255 || text.back()==L'.' || text.back()==L' ' || ++count>64)throw std::runtime_error("Invalid Lua log path");for(auto c:text)if(c<32 || std::wstring_view(L"<>\"|?*").find(c)!=std::wstring_view::npos)throw std::runtime_error("Invalid Lua log path");auto stem=text.substr(0,text.find(L'.'));for(auto& c:stem)c=wchar_t(std::towupper(c));if(stem==L"CON" || stem==L"PRN" || stem==L"AUX" || stem==L"NUL" || (stem.size()==4 && (stem.starts_with(L"COM") || stem.starts_with(L"LPT")) && stem[3]>=L'1' && stem[3]<=L'9'))throw std::runtime_error("Invalid Lua log path");}if(!count || !path.has_filename())throw std::runtime_error("Invalid Lua log path");relative_=std::move(path);path_=std::string(value);}
void LuaFileLog::write(std::string_view value) const{
    validateWar3UserDirectory(dataRoot_);auto user=war3UserDirectory();fs::create_directories(user);std::vector<std::shared_ptr<void>> held;auto hold=[&](const fs::path& path){if(!CreateDirectoryW(path.c_str(),nullptr) && GetLastError()!=ERROR_ALREADY_EXISTS)throw std::runtime_error("Cannot create Lua log directory: "+winError());auto handle=CreateFileW(path.c_str(),FILE_READ_ATTRIBUTES,FILE_SHARE_READ|FILE_SHARE_WRITE,nullptr,OPEN_EXISTING,FILE_FLAG_BACKUP_SEMANTICS|FILE_FLAG_OPEN_REPARSE_POINT,nullptr);if(handle==INVALID_HANDLE_VALUE)throw std::runtime_error("Cannot open Lua log directory: "+winError());std::shared_ptr<void> guard(handle,[](void* value){CloseHandle(value);});FILE_ATTRIBUTE_TAG_INFO info{};if(!GetFileInformationByHandleEx(handle,FileAttributeTagInfo,&info,sizeof(info)) || !(info.FileAttributes&FILE_ATTRIBUTE_DIRECTORY) || (info.FileAttributes&FILE_ATTRIBUTE_REPARSE_POINT))throw std::runtime_error("Invalid Lua log directory");held.push_back(std::move(guard));};auto directory=user/L"LuaLogs";hold(directory);for(auto& part:relative_.parent_path()){directory/=part;hold(directory);}auto target=directory/relative_.filename();auto handle=CreateFileW(target.c_str(),FILE_APPEND_DATA|FILE_READ_ATTRIBUTES,FILE_SHARE_READ,nullptr,OPEN_ALWAYS,FILE_ATTRIBUTE_NORMAL|FILE_FLAG_OPEN_REPARSE_POINT,nullptr);if(handle==INVALID_HANDLE_VALUE)throw std::runtime_error("Cannot open Lua log: "+winError());std::shared_ptr<void> guard(handle,[](void* value){CloseHandle(value);});FILE_ATTRIBUTE_TAG_INFO info{};if(!GetFileInformationByHandleEx(handle,FileAttributeTagInfo,&info,sizeof(info)) || (info.FileAttributes&(FILE_ATTRIBUTE_DIRECTORY|FILE_ATTRIBUTE_REPARSE_POINT)))throw std::runtime_error("Invalid Lua log file");if(value.size()>1024u*1024u)throw std::runtime_error("Lua log output exceeds budget");DWORD written=0;if(!WriteFile(handle,value.data(),DWORD(value.size()),&written,nullptr) || written!=value.size())throw std::runtime_error("Cannot write Lua log: "+winError());
}
}
